export const GENERATED_COLLECTIBLES: GeneratedCollectible[] = [{"id":"1","title":"Samian ware bowl","caption":"This near complete cylindrical bowl is made of terra sigillata, commonly known as Samian ware. Terra sigillata is famous for its red glaze, an effect produced by colouring ordinary glass with red iron oxide, finely ground, and mixed in a thin water slip solution. When fired, the moulded and incised ornaments on the vessels remain visible and distinguishable through the delicate glaze.\n\nThis bowl was found at the Roman town of Calleva, near Silchester, during excavations by the Society of Antiquaries in the late 19th and early 20th centuries.\n\nHeight = 12 cm\n\nObject number REDMG : 1995.81.1\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/46ea6b2a3ff54e58908905985edd4dfa/embed","attributionUrl":"https://sketchfab.com/3d-models/samian-ware-bowl-46ea6b2a3ff54e58908905985edd4dfa","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"2","title":"Roman bone spoon","caption":"This spoon was found at the Roman town of Calleva, near Silchester, during excavations in the 19th and 20th centuries. The spoon, made of animal bone, has a shallow circular bowl and straight handle. The handle extends under the bowl in a v-shape.\n\nLength = 10.2 cm\n\nObject number REDMG : 1995.86.87\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/0170cd31d50f4abaa3c70ae5bee5f5f6/embed","attributionUrl":"https://sketchfab.com/3d-models/roman-bone-spoon-0170cd31d50f4abaa3c70ae5bee5f5f6","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"3","title":"Roman penannular brooch","caption":"This penannular brooch was found at the Roman town of Calleva, near Silchester, during excavations by the Society of Antiquaries between 1890 and 1909.\n\nPenannular brooches were common in Roman Britain. They were used to secure clothing. This metal brooch has a hinged pin, which is slightly bent and worn through use.\n\nDiameter = 35 mm\n\nObject number REDMG : 1995.2.296\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/18d3b32cf8754b1081e3876b69ec2b3e/embed","attributionUrl":"https://sketchfab.com/3d-models/roman-penannular-brooch-18d3b32cf8754b1081e3876b69ec2b3e","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"4","title":"Roman key","caption":"This iron key was found at the Roman town of Calleva, near Silchester, during excavations by the Society of Antiquaries in the late nineteenth century. It is a Roman L-shaped tumbler lock key. A tumbler lock has tumblers which are moved clear of the bolt by the key.\n\nLength = 17 cm\n\nObject number REDMG : 1995.96.48\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/9e6ec47a8e4f43de886ed789f217946b/embed","attributionUrl":"https://sketchfab.com/3d-models/roman-key-9e6ec47a8e4f43de886ed789f217946b","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"5","title":"Roman mortarium with food remains","caption":"This pottery mortarium was found at the Roman town of Calleva, near Silchester, during an excavation by the Society of Antiquaries in the late nineteenth century. It probably dates to between 180 and 239 AD and originates from an Oxfordshire kiln. The mortarium would have been used to grind up foods and spices. This one still contains the remains of food pulp comprising varieties of cherry and plum. One of these fruits must have been preserved because they ripen at different times of the year.\n\nDiameter = 22.5 cm\n\nObject number REDMG : 1992.1.1611\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/e1391760b12e400e820c53af21759d30/embed","attributionUrl":"https://sketchfab.com/3d-models/roman-mortarium-with-food-remains-e1391760b12e400e820c53af21759d30","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"6","title":"Beaker with scale decoration","caption":"This partly reconstructed colour-coated ware beaker was made in Gaul, modern day France. The raised scale decoration is barbotine, from the French word for slip, a mixture of clay and water. It probably dates to between 200 and 299 AD. The beaker made its way to Britain and was found at the Roman town of Calleva, near Silchester, during excavations by the Society of Antiquaries in the late 19th and early 20th centuries.\n\nObject number REDMG : 1992.1.324\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/400534c5aa64481298081cc1811434e6/embed","attributionUrl":"https://sketchfab.com/3d-models/beaker-with-scale-decoration-400534c5aa64481298081cc1811434e6","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"7","title":"Enamelled brooch","caption":"This brooch was found at the Roman town of Calleva, near Silchester, during excavations by the Society of Antiquaries in the late 19th century and early 20th century. It is a 2nd century Roman bronze disc brooch with enamel decoration. The sprung pin from the back is missing.\n\nDiameter = 3.5 cm\n\nObject number REDMG : 1995.2.336\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/b0993476afad4f1b885c3c056fa84dfe/embed","attributionUrl":"https://sketchfab.com/3d-models/enamelled-brooch-b0993476afad4f1b885c3c056fa84dfe","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"8","title":"Roman tile with dog paw prints","caption":"This tile was found at the Roman town of Calleva, near Silchester, during excavations in the 19th and 20th centuries. This tile is impressed with the footprints of two dogs. The prints tell us that tiles were made in the local vicinity and that tiles weren’t wasted, even those spoilt by animals walking across them whilst drying.\n\nLength = 31.5 cm\n\nObject number REDMG : 1995.98.59\n\n3D scanned on 10 January 2024, by Steven Dey, ThinkSee3D Ltd","embedSrc":"https://sketchfab.com/models/ab41657bf6b84cfb9579d16e7b3d99f5/embed","attributionUrl":"https://sketchfab.com/3d-models/roman-tile-with-dog-paw-prints-ab41657bf6b84cfb9579d16e7b3d99f5","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"9","title":"The Silchester Eagle","caption":"This cast bronze figure of an eagle, known as the Silchester Eagle, was found in the Basilica of the Roman town of Calleva, near Silchester in Hampshire, on the 9th October 1866 during excavations undertaken by Revd J.G. Joyce.\n\nThe bird is posed with its wings outstretched, its head raised and turned to the right. The original wings are missing, but it is clear, from the careful modelling of the feathers beneath them, that they must have been extended and raised.\n\nIn 1962, Jocelyn Toynbee described the eagle as ‘by far the most superbly naturalistic rendering of any bird or beast as yet yielded by Roman Britain’. It has captured the imaginations of generations of people, including Rosemary Sutcliffe and her novel The Eagle of the Ninth.\n\nLearn more about the Silchester Eagle on the Reading Museum website.\n\nScan by ThinkSee3D\n\nMuseum object number REDMG : 1995.4.1\n\nlength 230 mm, height 150 mm","embedSrc":"https://sketchfab.com/models/4a8d82aefb3b46e98f8539410931bbeb/embed","attributionUrl":"https://sketchfab.com/3d-models/the-silchester-eagle-4a8d82aefb3b46e98f8539410931bbeb","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"10","title":"The Ogham stone from Silchester","caption":"In 1893, excavators at the Roman town of Silchester (Calleva Atrebatum), Hampshire, discovered a battered small column, about 60cm tall, top-down in a well that had been dug through the foundations of a ruined house. Only when they cleaned it did they realise what they had found. Washing the stone revealed markings which were identified as an ‘inscription written in Ogham characters’. It remains the most easterly find of an Ogham stone to date.\n\nLearn more about this stone on the Reading Museum website, including the meaning of the inscription, the person to whom it was dedicated, and its significance within the wider context of the Roman town of Silchester.\n\nObject number REDMG : 1995.1.24\n\n3D scanned on 14 February 2022, by Steven Dey, ThinkSee3D Ltd.","embedSrc":"https://sketchfab.com/models/153ed90f03a14ff290e1ec39ee07dfe2/embed","attributionUrl":"https://sketchfab.com/3d-models/the-ogham-stone-from-silchester-153ed90f03a14ff290e1ec39ee07dfe2","author":"ReadingMuseum","authorUrl":"https://sketchfab.com/ReadingMuseum","kind":"artefact"},{"id":"11","title":"Silchester temple site. Well.","caption":"This Roman well was excavated by Kevin Standage. More info to follow.","embedSrc":"https://sketchfab.com/models/d6b3d99642c1479ea2f9e962d46fad2d/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-temple-site-well-d6b3d99642c1479ea2f9e962d46fad2d","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site"},{"id":"12","title":"Silchester Baths 2021 Context 3260 buttress","caption":"Just beyond the Caldarium, to the East, is this buttress, which may belong to the earlier Neronian bath house. Since this model was created we have excavated further and more walls, contemporary with this structure have emerged. The walls at the east end of the Bath house are built with much deeper foundations because the ground at the east end is very wet due to the Iron Age ditch just a few metres east, and the spring which carried away the run off from the drains of the baths to this ditch.","embedSrc":"https://sketchfab.com/models/172f1a31a87a41799f6d8710b9b96724/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-baths-2021-context-3260-buttress-172f1a31a87a41799f6d8710b9b96724","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":189,"z":145},{"id":"13","title":"Silchester Baths 2021. C3307","caption":"Trench 5. At the east end of the Caldarium to the west of the apse at this end this feature is comprised of scorched earth, and a layer of charcoal deposit was in this arched hollow. It is one of the heat sources or stoke holes for heating this building where the hot air would have been circulated between the pilae of the hypocaust. Photographed by student Cat jenkins.","embedSrc":"https://sketchfab.com/models/a60a9e51a3a74febb87e26d69ef7005e/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-baths-2021-c3307-a60a9e51a3a74febb87e26d69ef7005e","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":183.3,"z":159.1},{"id":"14","title":"Silchester Baths 2021. C3315","caption":"Trench 5. At the east end of the Caldarium immediately to the west of the apse (which you can see in this image) at this end this feature is comprised of a thick charcoal deposit Part of one of the hearths for heating this building. Context 3315 is an L shaped cut within this feature. Excavated and Photographed by student Rachel Hunt.","embedSrc":"https://sketchfab.com/models/54bb30d153cb40dc8e952ce08c860c83/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-baths-2021-c3315-54bb30d153cb40dc8e952ce08c860c83","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":168.3,"z":167.8},{"id":"15","title":"Silchester Baths 2021. Small skeleton","caption":"Trench 4. Within a ditch fill we found some tiny articulated bones. We thought at first that they were of a premature human baby/Neonate. (identification TBC). They would be very tiny to plan, so we created a model with a macro lens, from which we can draw a plan at a later date. There is another layer of bones beneath, also photographed.","embedSrc":"https://sketchfab.com/models/743a011a7912472eb647bfea7c69b553/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-baths-2021-small-skeleton-743a011a7912472eb647bfea7c69b553","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":149.7,"z":167.8},{"id":"16","title":"Silchester Baths 2021. Walls C2119, C2264, C2265","caption":"Trench 2. Southern Walls of the Ambulatory. Elevation running E to W.","embedSrc":"https://sketchfab.com/models/438a832d262b4153aff64064e0dd9801/embed","attributionUrl":"https://sketchfab.com/3d-models/silchester-baths-2021-walls-c2119-c2264-c2265-438a832d262b4153aff64064e0dd9801","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":134.7,"z":159.1},{"id":"17","title":"Plunge Pool Trench 4","caption":"Plunge Pool Trench 4","embedSrc":"https://sketchfab.com/models/dcd204a5d8a34e218adb4b396ed17d22/embed","attributionUrl":"https://sketchfab.com/3d-models/plunge-pool-trench-4-dcd204a5d8a34e218adb4b396ed17d22","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":129,"z":145},{"id":"18","title":"Rubble Plinth Trench 4","caption":"Rubble Plinth Trench 4","embedSrc":"https://sketchfab.com/models/1796f75589d340d7b8d6fbb152d2d546/embed","attributionUrl":"https://sketchfab.com/3d-models/rubble-plinth-trench-4-1796f75589d340d7b8d6fbb152d2d546","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":134.7,"z":130.9},{"id":"19","title":"Timbers TR3 (pre dendro sample).","caption":"The horizontal oak sill beam, and two other substantial underpinning timbers under the Easternmost wall of the Tepidarium in Trench 3. Before sawing for Dendro chronology sampling. Contexts 3330 and 3337. Silchester Baths 2021.","embedSrc":"https://sketchfab.com/models/8b146acac9204ae697e45f816ce8ee62/embed","attributionUrl":"https://sketchfab.com/3d-models/timbers-tr3-pre-dendro-sample-8b146acac9204ae697e45f816ce8ee62","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":149.7,"z":122.2},{"id":"20","title":"Silchester Baths 2021. Ambulatory floors. A photogram to show the layers within the western slot in Trench 2. The Ambulatory. We see pink layers of opus signinum mortar interspersed with grey silts, suggesting episodes of flooding and re-surfacing.","caption":"Ambulatory floors. TR2 western slot sections","embedSrc":"https://sketchfab.com/models/c6a7c89d88f94ef099a95c17cc469b01/embed","attributionUrl":"https://sketchfab.com/3d-models/ambulatory-floors-tr2-western-slot-sections-c6a7c89d88f94ef099a95c17cc469b01","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":168.3,"z":122.2},{"id":"21","title":"Herringbone Floor Trench 4","caption":"Trench 4","embedSrc":"https://sketchfab.com/models/6b1860b65804414e93dffa8105092e30/embed","attributionUrl":"https://sketchfab.com/3d-models/herringbone-floor-trench-4-6b1860b65804414e93dffa8105092e30","author":"University of Reading - Archaeology Department","authorUrl":"https://sketchfab.com/UoR-Archaeology","kind":"site","x":183.3,"z":130.9}];
